// Synthetic season topology around the real 2402377 report structure, for tests
// only. These generated bytes/IDs are never operational capture evidence.
import {readFileSync,writeFileSync} from 'node:fs'
import {join} from 'node:path'
import {sha} from './vklopi-dfb-regijo.mjs'
export function syntheticCapture(dir,year=2025){
 const template=readFileSync(new URL('./vzorci/de-dfb-2402377.html',import.meta.url),'utf8')
 const clubs=['rot-weiss-oberhausen',...Array.from({length:17},(_,i)=>`club-${i+1}`)],ring=[...clubs],matches=[],pages=new Map(),root='https://datencenter.dfb.de',path=`regionalliga-west/seasons/${year}-${year+1}`
 for(let r=0;r<17;r++){
  for(let i=0;i<9;i++){const [home,away]=[ring[i],ring[17-i]];matches.push({round:r+1,home,away},{round:r+18,home:away,away:home})}
  ring.splice(1,0,ring.pop())
 }
 for(const [i,m]of matches.entries()){
  m.id=String((year===2025?8000000:9000000)+i);m.url=`${root}/datencenter/regionalliga-west/${year}-${year+1}/${m.round}-spieltag/${m.home}-${m.away}-${m.id}`
  const body=template.replaceAll('sc-paderborn-07-ii-1-fc-bocholt-2402377',`${m.home}-${m.away}-${m.id}`).replaceAll('22-spieltag',`${m.round}-spieltag`).replaceAll('22. Spieltag',`${m.round}. Spieltag`).replaceAll('sc-paderborn-07-ii',m.home).replaceAll('1-fc-bocholt',m.away).replaceAll('SC Paderborn 07 II',m.home).replaceAll('1. FC Bocholt',m.away)
   .replaceAll('2025-2026',`${year}-${year+1}`).replaceAll('2025/2026',`${year}/${year+1}`).replaceAll('2025/26',`${year}/${String(year+1).slice(2)}`).replaceAll('15. Februar 2026',year===2025?'15. Februar 2026':'15. August 2026')
  pages.set(m.url,body)
 }
 for(const club of clubs){
  const url=`${root}/competitions/${path}/teams/${club}`,rows=matches.filter(m=>m.home===club||m.away===club).map(m=>{
   const cell=(side,name)=>`<div class="c-MatchTable-team c-MatchTable-team--${side}"><a href="${root}/competitions/${path}/teams/${name}">${name}</a></div>`
   return `<div class="c-MatchTable-row"><div id="match_${m.id}"><div class="c-MatchTable-description">Samstag, ${year===2025?'15.02.2026':'15.08.2026'} 14:00 Uhr</div></div>${cell('home',m.home)}<div class="c-MatchTable-score"><a href="${m.url}">0 : 0</a></div>${cell('away',m.away)}</div>`
  })
  pages.set(url,`<!doctype html><html><head><link rel="canonical" href="${url}"></head><body>${rows.join('')}</body></html>`)
 }
 const at=new Date(Date.now()-60000).toISOString(),records=[]
 for(const [url,body]of pages){const sha256=sha(body),file=sha256+'.html';writeFileSync(join(dir,file),body);records.push({url,at,sha256,file})}
 writeFileSync(join(dir,'prenosi.json'),JSON.stringify(records)+'\n')
 writeFileSync(join(dir,'porocilo.json'),JSON.stringify({vir:'dfb',koda:`regionalliga-west/${year}-${year+1}`,sezona:`${year}/${String(year+1).slice(2)}`,prenesenih:324,krogov:34,klubov:18,odigranih:306,pripravljeno:false,napake:['synthetic old parser: unsupported 90+39'],opozorila:[]}))
 writeFileSync(join(dir,'razpored.json'),'[]');writeFileSync(join(dir,'zapisniki.json'),'[]')
 return records
}
